// main.zig — Egyfájlos Zig backend, SSE streaminggel és Exa Fast integrációval
// Zig 0.12.xhez igazítva. Szükséges env: CEREBRAS_API_KEY, EXA_API_KEY. [web:45]

const std = @import("std");

const CEREBRAS_URL = ""; // Chat Completions SSE [web:11]
const EXA_URL      = "";                    // Exa Search API [web:17]

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer if (gpa.deinit() == .leak) @panic("leak");
    const alloc = gpa.allocator();

    // Ellenőrzés: API kulcsok
    const cereKey = try requireEnv(alloc, "CEREBRAS_API_KEY");
    defer alloc.free(cereKey);
    const exaKey = try requireEnv(alloc, "EXA_API_KEY");
    defer alloc.free(exaKey);

    // Tartós HTTP kliens(ek) TLSsel, keepalive (connection pool) [web:44][web:50]
    var http_client = std.http.Client{ .allocator = alloc };
    defer http_client.deinit();

    // HTTP szerver indítása (std.http.Server) [web:44][web:45]
    var server = std.http.Server.init(alloc, .{ .reuse_address = true });
    defer server.deinit();

    const addr = try std.net.Address.parseIp4("0.0.0.0", 8080);
    try server.listen(addr);

    // Fő loop
    while (true) {
        var res = try server.accept(.{});
        res.thread_pool = null;
        handle(&res, &http_client, alloc, cereKey, exaKey) catch |e| {
            // Besteffort hiba lecsatolás
            std.log.err("hiba: {}", .{e});
        };
    }
}

fn requireEnv(alloc: std.mem.Allocator, name: []const u8) ![]u8 {
    const v = std.process.getEnvVarOwned(alloc, name) catch return error.MissingEnvVar;
    if (v.len == 0) return error.MissingEnvVar;
    return v;
}

fn handle(
    res: std.http.Server.Connection,
    client: std.http.Client,
    alloc: std.mem.Allocator,
    cereKey: []const u8,
    exaKey: []const u8,
) !void {
    var req = try res.reader();
    var w = res.writer();

    var headers = std.http.Headers{ .allocator = alloc };
    defer headers.deinit();

    var request = std.http.Request{};
    try request.parse(alloc, &req);
    defer request.deinit();

    const method = request.method;
    const path = request.target;

    if (method == .GET and std.mem.eql(u8, path, "/")) {
        // index.html kiszolgálása [web:45]
        const file = try std.fs.cwd().openFile("index.html", .{});
        defer file.close();
        const size = try file.getEndPos();
        try res.sendStatus(.ok);
        try res.sendHeader("ContentType", "text/html; charset=utf8");
        try res.sendHeader("ContentLength", std.fmt.allocPrint(alloc, "{}", .{size}) catch "0");
        try res.finishHeaders();
        // zerocopy stream
        var bw = res.writer();
        try std.io.copy(file.reader(), bw);
        return;
    }

    if (method == .POST and std.mem.eql(u8, path, "/api/chat")) {
        // Test beolvasása, JSONból message kivétele [web:45]
        const body = try request.reader().readAllAlloc(alloc, 1_000_000);
        defer alloc.free(body);
        const msg = try extractJsonString(alloc, body, "message");
        defer alloc.free(msg);

        // SSE fejlécek [web:11]
        try res.sendStatus(.ok);
        try res.sendHeader("ContentType", "text/eventstream");
        try res.sendHeader("CacheControl", "nocache");
        try res.sendHeader("Connection", "keepalive");
        try res.finishHeaders();

        // Cerebras streaming proxy [web:11][web:2]
        try streamCerebras(res, client, alloc, cereKey, msg, 2048);
        return;
    }

    if (method == .POST and std.mem.eql(u8, path, "/api/deepsearch")) {
        // Mélykutatás: előbb Exa Fast keresés, majd hosszú Cerebras stream [web:17][web:11]
        const body = try request.reader().readAllAlloc(alloc, 1_000_000);
        defer alloc.free(body);
        const q = try extractJsonString(alloc, body, "query");
        defer alloc.free(q);

        // Exa fast (numResults=30, livecrawl=never) [web:17]
        const hits = try exaFast(client, alloc, exaKey, q, 30);
        defer alloc.free(hits);

        try res.sendStatus(.ok);
        try res.sendHeader("ContentType", "text/eventstream");
        try res.sendHeader("CacheControl", "nocache");
        try res.sendHeader("Connection", "keepalive");
        try res.finishHeaders();

        // A találatokat felhasználva kérünk hosszú streamelt választ [web:11][web:2]
        try streamCerebrasDeep(res, client, alloc, cereKey, q, hits, 65536);
        return;
    }

    // 404 [web:45]
    try res.sendStatus(.not_found);
    try res.sendHeader("ContentType", "text/plain; charset=utf8");
    try res.finishHeaders();
    try w.print("Not Found\n", .{});
}

fn extractJsonString(alloc: std.mem.Allocator, raw: []const u8, key: []const u8) ![]u8 {
    var p = std.json.Parser.init(alloc, .{});
    defer p.deinit();
    const tree = try p.parse(raw);
    defer tree.deinit();
    const v = tree.root.Object.get(key) orelse return error.BadRequest;
    return try alloc.dupe(u8, v.String);
}

fn exaFast(
    client: std.http.Client,
    alloc: std.mem.Allocator,
    exaKey: []const u8,
    query: []const u8,
    numResults: usize,
) ![]u8 {
    // Minimális késleltetés: type="fast", livecrawl="never" [web:17]
    const payload = try std.fmt.allocPrint(
        alloc,
        "{{\"query\":\"{s}\",\"type\":\"fast\",\"numResults\":{d},\"livecrawl\":\"never\"}}",
        .{ jsonEscapeAlloc(alloc, query) catch query, numResults },
    );
    defer alloc.free(payload);

    var uri = try std.Uri.parse(EXA_URL);
    var headers = std.http.Headers{ .allocator = alloc };
    defer headers.deinit();
    try headers.append("Authorization", try bearer(alloc, exaKey));
    try headers.append("ContentType", "application/json");
    try headers.append("Connection", "keepalive");

    var req = try client.request(.POST, uri, headers, .{});
    defer req.deinit();
    try req.start();
    try req.writeAll(payload);
    try req.finish();

    const rsp = try req.reader().readAllAlloc(alloc, 5_000_000);
    return rsp;
}

fn streamCerebras(
    res: std.http.Server.Connection,
    client: std.http.Client,
    alloc: std.mem.Allocator,
    cereKey: []const u8,
    userMsg: []const u8,
    maxTokens: usize,
) !void {
    // Chat Completions SSE: choices[0].delta.content csorgatása [web:11][web:2]
    const payload = try std.fmt.allocPrint(
        alloc,
        "{{\"model\":\"gptoss120b\",\"stream\":true,\"max_completion_tokens\":{d},\"messages\":[{{\"role\":\"system\",\"content\":\"Magyarul, tömören válaszolj.\"}},{{\"role\":\"user\",\"content\":\"{s}\"}}]}}",
        .{ maxTokens, jsonEscapeAlloc(alloc, userMsg) catch userMsg },
    );
    defer alloc.free(payload);
    try forwardSSE(res, client, alloc, cereKey, payload);
}

fn streamCerebrasDeep(
    res: std.http.Server.Connection,
    client: std.http.Client,
    alloc: std.mem.Allocator,
    cereKey: []const u8,
    q: []const u8,
    hitsJson: []const u8,
    maxTokens: usize,
) !void {
    // Hosszú, tagolt jelentés kérése a találatok (JSON) felhasználásával [web:11][web:2]
    const payload = try std.fmt.allocPrint(
        alloc,
        "{{\"model\":\"gptoss120b\",\"stream\":true,\"max_completion_tokens\":{d},\"messages\":["
        ++ "{{\"role\":\"system\",\"content\":\"Magyar ügynök vagy. Adj hosszú, tagolt, hivatkozott jelentést a megadott találatok alapján.\"}},"
        ++ "{{\"role\":\"user\",\"content\":\"Kérdés: {s}\"}},"
        ++ "{{\"role\":\"user\",\"content\":\"Találatok (JSON): {s}\"}}]}",
        .{
            maxTokens,
            jsonEscapeAlloc(alloc, q) catch q,
            jsonEscapeAlloc(alloc, hitsJson) catch hitsJson,
        },
    );
    defer alloc.free(payload);
    try forwardSSE(res, client, alloc, cereKey, payload);
}

fn forwardSSE(
    res: std.http.Server.Connection,
    client: std.http.Client,
    alloc: std.mem.Allocator,
    cereKey: []const u8,
    jsonBody: []const u8,
) !void {
    var uri = try std.Uri.parse(CEREBRAS_URL);
    var headers = std.http.Headers{ .allocator = alloc };
    defer headers.deinit();
    try headers.append("Authorization", try bearer(alloc, cereKey));
    try headers.append("ContentType", "application/json");
    try headers.append("Accept", "text/eventstream");
    try headers.append("Connection", "keepalive");

    var req = try client.request(.POST, uri, headers, .{});
    defer req.deinit();
    try req.start();
    try req.writeAll(jsonBody);
    try req.finish();

    // Válasz soronként olvasása, "data: " sorok továbbítása [web:11]
    var rdr = req.reader();
    var buf_reader = std.io.bufferedReader(rdr);
    var in_stream = buf_reader.reader();

    var out = res.writer();
    while (true) {
        var line = try in_stream.readUntilDelimiterOrEofAlloc(alloc, '\n', 1 << 16);
        if (line.len == 0) break;
        defer alloc.free(line);

        // Trim CRLF
        const trimmed = trimLine(line);
        if (std.mem.startsWith(u8, trimmed, "data: ")) {
            // Továbbítjuk teljes egészében (Cerebras SSE JSON chunk) [web:11]
            try out.print("{s}\n\n", .{ trimmed });
        }
        // A “[DONE]” jelzőt az ügyféloldal a data: sorból kapja meg [web:11]
    }
}

fn trimLine(s: []const u8) []const u8 {
    var b = s;
    while (b.len > 0 and (b[b.len  1] == '\r' or b[b.len  1] == '\n')) b = b[0 .. b.len  1];
    return b;
}

fn bearer(alloc: std.mem.Allocator, key: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "Bearer {s}", .{ key });
}

fn jsonEscapeAlloc(alloc: std.mem.Allocator, s: []const u8) ![]u8 {
    var list = std.ArrayList(u8).init(alloc);
    errdefer list.deinit();
    try std.json.writeString(list.writer(), s);
    return list.toOwnedSlice();
}
