        chatOut.textContent = '';
        ssePost('/api/chat', { message: chatInput.value },
          c => chatOut.textContent += c,
          () => {},
          e => chatOut.innerHTML = '<span class="err">' + e.message + '</span>'
        );
      };

      // Mélykutatás
      const deepQ = document.getElementById('deepQ');
      const deepOut = document.getElementById('deepOut');
      const deepStatus = document.getElementById('deepStatus');
      document.getElementById('deepBtn').onclick = () => {
        deepOut.textContent = '';
        deepStatus.textContent = 'Fut… ez hosszabb ideig tarthat.';
        ssePost('/api/deepsearch', { query: deepQ.value },
          c => deepOut.textContent += c,
          () => deepStatus.textContent = 'Kész.',
          e => deepStatus.innerHTML = '<span class="err">' + e.message + '</span>'
        );
      };
    </script>
