        ++ "{{\"role\":\"system\",\"content\":\"Magyar ügynök vagy. Adj hosszú, tagolt, hivatkozott jelentést a megadott találatok alapján.\"}},"
        ++ "{{\"role\":\"user\",\"content\":\"Kérdés: {s}\"}},"
        ++ "{{\"role\":\"user\",\"content\":\"Találatok (JSON): {s}\"}}]}",
        .{
            maxTokens,
            jsonEscapeAlloc(alloc, q) catch q,
            jsonEscapeAlloc(alloc, hitsJson) catch hitsJson,
        },
    );
    defer alloc.free(payload);
    try forwardSSE(res, client, alloc, cereKey, payload);
}

fn forwardSSE(
    res: std.http.Server.Connection,
    client: std.http.Client,
    alloc: std.mem.Allocator,
    cereKey: []const u8,
    jsonBody: []const u8,
) !void {
    var uri = try std.Uri.parse(CEREBRAS_URL);
    var headers = std.http.Headers{ .allocator = alloc };
    defer headers.deinit();
    try headers.append("Authorization", try bearer(alloc, cereKey));
    try headers.append("ContentType", "application/json");
    try headers.append("Accept", "text/eventstream");
    try headers.append("Connection", "keepalive");

    var req = try client.request(.POST, uri, headers, .{});
    defer req.deinit();
    try req.start();
    try req.writeAll(jsonBody);
    try req.finish();

    // Válasz soronként olvasása, "data: " sorok továbbítása [web:11]
    var rdr = req.reader();
    var buf_reader = std.io.bufferedReader(rdr);
    var in_stream = buf_reader.reader();

    var out = res.writer();
    while (true) {
        var line = try in_stream.readUntilDelimiterOrEofAlloc(alloc, '\n', 1 << 16);
        if (line.len == 0) break;
        defer alloc.free(line);

        // Trim CRLF
        const trimmed = trimLine(line);
        if (std.mem.startsWith(u8, trimmed, "data: ")) {
            // Továbbítjuk teljes egészében (Cerebras SSE JSON chunk) [web:11]
            try out.print("{s}\n\n", .{ trimmed });
        }
        // A “[DONE]” jelzőt az ügyféloldal a data: sorból kapja meg [web:11]
    }
}

fn trimLine(s: []const u8) []const u8 {
    var b = s;
    while (b.len > 0 and (b[b.len  1] == '\r' or b[b.len  1] == '\n')) b = b[0 .. b.len  1];
    return b;
}

fn bearer(alloc: std.mem.Allocator, key: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "Bearer {s}", .{ key });
}

fn jsonEscapeAlloc(alloc: std.mem.Allocator, s: []const u8) ![]u8 {
    var list = std.ArrayList(u8).init(alloc);
    errdefer list.deinit();
    try std.json.writeString(list.writer(), s);
    return list.toOwnedSlice();
}
